@import url('./css/build.css');
.pictrueTab {
    width: 40px !important;
    height: 40px !important;
    cursor pointer
    img{
        width 100%;
        height 100%;
    }
}
.upLoad {
    width: 58px;
    height: 58px;
    line-height: 58px;
    border: 1px dotted rgba(0, 0, 0, 0.1);
    border-radius: 4px;
    background: rgba(0, 0, 0, 0.02);
    cursor: pointer;
}
.diy-table .diy-button{
    margin-top: 10px;
}
/deep/.ivu-table-cell{
    padding 0!important;
}
.diy_table{
    box-sizing: border-box;
    position: relative;
    &:before{
        content:"";
        width:1px;
        height:100%;
        background: #eee;
        position: absolute;
        top:0;
        left:0;
    }
    &:after{
        content:"";
        width:1px;
        height:100%;
        background: #eee;
        position: absolute;
        top:0;
        right:0;
    }
}
.delete{
    color: #57a3f3;
    cursor pointer;
}
